CREATE TYPE "RoomStatus" AS ENUM ('LOBBY','PLAYING','EXPIRED');
CREATE TYPE "SessionStatus" AS ENUM ('ACTIVE','COMPLETE');
CREATE TABLE "Room" ("id" TEXT PRIMARY KEY,"code" VARCHAR(6) NOT NULL UNIQUE,"status" "RoomStatus" NOT NULL DEFAULT 'LOBBY',"selectedGame" TEXT NOT NULL DEFAULT 'read-my-mind',"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "RoomPlayer" ("id" TEXT PRIMARY KEY,"roomId" TEXT NOT NULL,"nickname" VARCHAR(24) NOT NULL,"tokenHash" TEXT NOT NULL UNIQUE,"isHost" BOOLEAN NOT NULL DEFAULT false,"connected" BOOLEAN NOT NULL DEFAULT false,"ready" BOOLEAN NOT NULL DEFAULT false,"joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastSeenAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RoomPlayer_roomId_fkey" FOREIGN KEY ("roomId") REFERENCES "Room"("id") ON DELETE CASCADE);
CREATE TABLE "Game" ("id" TEXT PRIMARY KEY,"title" TEXT NOT NULL,"tagline" TEXT NOT NULL,"description" TEXT NOT NULL,"duration" TEXT NOT NULL,"intensity" INTEGER NOT NULL,"available" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "GameCard" ("id" TEXT PRIMARY KEY,"gameId" TEXT NOT NULL,"type" TEXT NOT NULL,"question" TEXT NOT NULL,"choices" JSONB NOT NULL,"intensity" INTEGER NOT NULL,"artworkPath" TEXT NOT NULL,"challenge" TEXT,"enabled" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "GameCard_gameId_fkey" FOREIGN KEY ("gameId") REFERENCES "Game"("id") ON DELETE CASCADE);
CREATE TABLE "GameSession" ("id" TEXT PRIMARY KEY,"roomId" TEXT NOT NULL,"gameId" TEXT NOT NULL,"status" "SessionStatus" NOT NULL DEFAULT 'ACTIVE',"currentRound" INTEGER NOT NULL DEFAULT 1,"stateVersion" INTEGER NOT NULL DEFAULT 0,"state" JSONB NOT NULL,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"endedAt" TIMESTAMP(3),CONSTRAINT "GameSession_roomId_fkey" FOREIGN KEY ("roomId") REFERENCES "Room"("id") ON DELETE CASCADE);
CREATE TABLE "SessionAction" ("id" TEXT PRIMARY KEY,"sessionId" TEXT NOT NULL,"actionId" TEXT NOT NULL,"playerId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SessionAction_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "GameSession"("id") ON DELETE CASCADE);
CREATE INDEX "Room_expiresAt_idx" ON "Room"("expiresAt"); CREATE INDEX "RoomPlayer_roomId_idx" ON "RoomPlayer"("roomId"); CREATE INDEX "GameCard_gameId_enabled_idx" ON "GameCard"("gameId","enabled"); CREATE INDEX "GameSession_roomId_status_idx" ON "GameSession"("roomId","status"); CREATE UNIQUE INDEX "SessionAction_sessionId_actionId_key" ON "SessionAction"("sessionId","actionId");
